import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync,writeFileSync} from 'node:fs';import {createEngine,installProjectRules,parseProject} from '@zge/sdk';import {kinds,projectFor} from './projects.mjs';
for(const kind of kinds)test(kind+' public rules, model/prefab, typo recovery, simulation and portable restore',async()=>{const p=await projectFor(kind);const bad=structuredClone(p);bad.rules[0].speed=0;await assert.rejects(createEngine({project:bad}));const wrong=structuredClone(p);wrong.rules.find(r=>r.kind==='goal').threshold=2;const debug=await createEngine({project:wrong});await debug.loadWorld();const debugKeys=new Set(['ArrowRight']);installProjectRules(debug,debugKeys);await debug.start();debug.pause();debug.step(30);assert.equal(debug.world.findEntity('pickup'),null);assert.equal(debug.world.findEntity('goal').components.goal.complete,false);const fixed=debug.exportProject();fixed.rules.find(r=>r.kind==='goal').threshold=1;await debug.dispose();const repaired=await createEngine({project:fixed});await repaired.loadWorld();installProjectRules(repaired);await repaired.start();repaired.pause();repaired.step(1);assert.equal(repaired.world.findEntity('goal').components.goal.complete,true);await repaired.dispose();const e=await createEngine({project:p}),s=await e.loadWorld();await e.importModel({id:'marker',bytes:new Uint8Array(readFileSync('triangle.glb')),license:{source:'self authored ZGE12 fixture',spdx:'CC0-1.0',redistribution:'permitted'}});s.createEntity({id:'model',name:'Imported marker',components:{transform:{position:[0,0,2],rotation:[0,0,0],scale:[1,1,1]},asset:{id:'marker'}}});e.createPrefab('marker-template','model');s.createPrefabInstance('marker-template');writeFileSync(kind+'.zge.json',JSON.stringify(e.exportProject()));const keys=new Set(['ArrowRight']);installProjectRules(e,keys);await e.start();e.pause();e.step(30);keys.clear();e.step(1);assert.equal(s.findEntity('pickup'),null);assert.equal(s.findEntity('goal').components.goal.complete,true);const exported=e.exportProject(),other=await createEngine({project:parseProject(JSON.stringify(exported))});await other.loadWorld();assert.deepEqual(other.world.serialize(),s.serialize());const lease=await other.acquireAsset('marker');assert.equal(lease.value.triangles,1);lease.release();await e.dispose();await other.dispose();});
